#!/usr/bin/env bash
# FINANSAL_ICGORU deploy — AI finansal içgörü (trend + ₺ etki + kaynak + simülasyon).
#  migration + server endpoint + mobil bölüm + desktop Vade paneli + desktop AI paneli. Rule 5: build+up. Idempotent.
set -e
cd /opt/krb-assessment
set -a; [ -f .env ] && . ./.env; set +a
PW="${POSTGRES_PASSWORD:-}"

if [ -f shells/saha.js ]; then SAHA=shells/saha.js; else SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*'|head -1); fi
if [ ! -f "$SAHA" ]; then echo "HATA: canlı saha.js yok"; exit 1; fi
KOK=shells/kokpit.html
if [ ! -f "$KOK" ]; then echo "HATA: shells/kokpit.html yok"; exit 1; fi
echo "saha=$SAHA  kokpit=$KOK"

cp server_container.mjs server_container.mjs.bak.$(date +%s)
cp "$SAHA" "$SAHA.bak.$(date +%s)"
cp "$KOK" "$KOK.bak.$(date +%s)"

echo "== 1) migration: bi_finansal_icgoru =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres \
  psql -U assessment_app -d assessment_platform -P pager=off <<'SQL'
CREATE TABLE IF NOT EXISTS bi_finansal_icgoru (
  tenant_id   uuid        NOT NULL,
  gun         date        NOT NULL,
  icgoruler   jsonb       NOT NULL DEFAULT '[]'::jsonb,
  baglam      jsonb,
  uretildi_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, gun)
);
SQL

echo "== 2) server endpoint + scheduler =="
printf '%s' '' | base64 -d > finicgoru_ep.py
python3 finicgoru_ep.py

echo "== 3) mobil bölüm (saha.js) =="
SDIR=$(dirname "$SAHA")
printf '%s' '' | base64 -d > "$SDIR/finicgoru_mobil.py"
( cd "$SDIR" && python3 finicgoru_mobil.py ) && rm -f "$SDIR/finicgoru_mobil.py"

echo "== 4) desktop Vade paneli (kokpit.html) =="
printf '%s' '' | base64 -d > shells/ovdesktop.py
( cd shells && python3 ovdesktop.py ) && rm -f shells/ovdesktop.py

echo "== 5) desktop AI paneli (kokpit.html) =="
printf '%s' '' | base64 -d > shells/finicgoru_desktop.py
( cd shells && python3 finicgoru_desktop.py ) && rm -f shells/finicgoru_desktop.py

echo "== syntax =="
node --check server_container.mjs && echo SERVER_OK
node --check "$SAHA" && echo SAHA_OK

echo "== docker build =="
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment

echo "== verify (server=2, saha=2, kokpit ovd=1 fin=1) =="
sleep 4
echo -n "server ODEME+FIN: "; docker exec krb-assessment sh -c "grep -c FINANSAL_ICGORU_V1 /app/server.mjs" || true
echo -n "saha fin: ";        docker exec krb-assessment sh -c "grep -c FINANSAL_ICGORU_MOBIL_V1 /app/shells/saha.js" || true
echo -n "kokpit vade: ";     docker exec krb-assessment sh -c "grep -c ODEME_VADELERI_DESKTOP_V1 /app/shells/kokpit.html" || true
echo -n "kokpit AI: ";       docker exec krb-assessment sh -c "grep -c FINANSAL_ICGORU_DESKTOP_V1 /app/shells/kokpit.html" || true
echo "== DONE =="
